#include "../Source/PluginProcessor.h"
#include "../Source/DistortionFX.h"
#include <iostream>
#include <stdexcept>
namespace {
void require(bool b,const char* message){if(!b)throw std::runtime_error(message);}
void set(SpaceInfinityProcessor& p,const juce::String& id,float value){auto* a=p.state.getParameter(id);require(a!=nullptr,"parameter exists");a->setValueNotifyingHost(a->convertTo0to1(value));}
}
int runCreativeSmoke(){try{
    for(int type=0;type<14;++type)for(int position=0;position<3;++position){studio::Distortion effect;effect.prepare(48000);studio::Distortion::Settings s;s.type=type;s.drive=.7f;s.mix=1;s.filterPosition=position;s.frequency=position==1?80:17000;s.q=position==2?10:.707f;s.filterMorph=.6f;effect.configure(s);double energy=0,mean=0;for(int i=0;i<96000;++i){const float input=.35f*std::sin(float(i)*.0576f)+.12f*std::sin(float(i)*.021f);const auto sample=effect.process(input,-input*.7f);for(float v:sample)require(std::isfinite(v)&&std::abs(v)<25,"all distortion modes and resonant filters remain finite");if(i>48000){energy+=sample[0]*sample[0];mean+=sample[0];}}require(energy>.001,"all modes produce audible output");require(std::abs(mean/48000)<.025,"wet DC blocker removes asymmetric offset");s.mix=0;effect.configure(s);for(int i=0;i<12000;++i)effect.process(.2f,-.1f);auto dry=effect.process(.2f,-.1f);require(std::abs(dry[0]-.2f)<1e-5f&&std::abs(dry[1]+.1f)<1e-5f,"zero wet mix restores exact dry signal");}
    const auto folder=juce::File::getSpecialLocation(juce::File::tempDirectory).getNonexistentChildFile("InfinityCreative",{},false);folder.createDirectory();auto p=std::make_unique<SpaceInfinityProcessor>(folder);p->loadPreset(1);set(*p,"distEnabled",1);set(*p,"distDrive",.71f);set(*p,"distMix",.63f);set(*p,"distType",12);set(*p,"distShape1_6",-.3f);p->state.state.setProperty("creator","Test Author",nullptr);p->state.state.setProperty("tags","Custom, Acid",nullptr);
    const int slot=p->presetBank().indexForKey("F1001");require(p->replaceBankPreset(slot).wasOk(),"factory replacement succeeds");set(*p,"distDrive",.2f);require(p->replaceBankPreset(slot).wasOk(),"second factory replacement succeeds");require(!folder.getChildFile("Backups").findChildFiles(juce::File::findFiles,false,"*.sipreset").isEmpty(),"previous factory edits retained");require(p->loadBankPreset(slot).wasOk(),"edited factory reload");require(std::abs(p->state.getRawParameterValue("distDrive")->load()-.2f)<1e-5f,"replacement sound recalls");require(p->state.state.getProperty("creator").toString()=="Test Author","replacement author recalls");
    const auto zip=folder.getChildFile("FactoryEdits.zip");require(p->presetBank().exportEdits(zip).wasOk(),"factory export ZIP");juce::ZipFile archive(zip);require(archive.getIndexOfFileName("F1001.sipreset")>=0,"stable key exported");
    auto before=p->presetBank().entries()[size_t(slot)].file;juce::MemoryBlock parentBefore;require(p->presetBank().read(slot,parentBefore).wasOk(),"read parent before hybrid");require(p->hybridisePresets(slot,p->presetBank().indexForKey("F1050"),.5f).wasOk(),"hybridise two sounds");require(p->selectedPresetKey()=="HYBRID"&&p->state.state.getProperty("tags").toString().contains("Hybrid"),"hybrid named and tagged");juce::MemoryBlock parentAfter;require(p->presetBank().read(slot,parentAfter).wasOk()&&parentBefore==parentAfter,"hybrid leaves parent untouched");require(p->saveNewPreset("Creative Hybrid").wasOk(),"hybrid saves as independent preset");
    p->loadPreset(0);set(*p,"distEnabled",1);set(*p,"distDrive",.7f);set(*p,"fxOutput8",-24);p->prepareToPlay(48000,256);juce::AudioBuffer<float> audio(2,256);float peak=0;for(int block=0;block<150;++block){juce::MidiBuffer midi;if(block==0)midi.addEvent(juce::MidiMessage::noteOn(1,60,.8f),0);p->processBlock(audio,midi);if(block>100)peak=std::max(peak,audio.getMagnitude(0,256));}require(peak<1e-6f,"distortion output minimum mutes stage");
    p.reset();folder.deleteRecursively();std::cout<<"Creative workflow: 14 distortion modes/filter positions, dry mix, DC, output mute, factory backups/ZIP, hybrid and metadata passed\n";return 0;
}catch(const std::exception& e){std::cerr<<"Creative workflow: "<<e.what()<<std::endl;return 170;}}
